def min_coins_to_color_grid(n, m, grid):
    # Initialize the cost matrix
    cost = [[0] * m for _ in range(n)]

    # Fill the cost matrix based on the target grid
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B':
                cost[i][j] = 1

    # Calculate the minimum coins needed
    total_cost = 0

