                cost[i][j] += cost[i-1][j]
            if j < m-1:
                cost[i][j] += cost[i][j+1]
            if i > 0 and j < m-1:
                cost[i][j] -= cost[i-1][j+1]
            total_cost += cost[i][j] * 4

    # Process the bottom-left corner
    for i in range(n-1, -1, -1):
        for j in range(m):
            if i < n-1:
                cost[i][j] += cost[i+1][j]
            if j > 0:
                cost[i][j] += cost[i][j-1]
            if i < n-1 and j > 0:
                cost[i][j] -= cost[i+1][j-1]
            total_cost += cost[i][j] * 2

    # Process the top-left corner
    for i in range(n):
        for j in range(m):
            if i > 0:
                cost[i][j] += cost[i-1][j]
            if j > 0:
                cost[i][j] += cost[i][j-1]
            if i > 0 and j > 0:
                cost[i][j] -= cost[i-1][j-1]
            total_cost += cost[i][j] * 1

    return total_cost

